def locate_skeleton(output_dir: Path, prefix: str, label: str) -> Path:
    """Find the NDskl file emitted by mse for the requested skeleton type."""
    suffix = SKELETON_SUFFIXES.get(label)
    if not suffix:
        raise ValueError(f"Unsupported skeleton label '{label}'.")
    canonical = output_dir / f"{prefix}{suffix}"
    if canonical.exists():
        return canonical
    pattern = f"{prefix}_*{suffix}"
    matches = sorted(output_dir.glob(pattern))
    if matches:
        return matches[-1]
    raise FileNotFoundError(
        "DisPerSE completed but no skeleton file was found. "
        f"Searched for '{canonical.name}' and pattern '{pattern}'."
    )


